{"task_id": "T25", "code": "def solve(matrix):
    """Determinant of a square integer matrix, via the fraction-free Bareiss algorithm."""
    n = len(matrix)
    if n == 0:
        return 1
    if any(len(row) != n for row in matrix):
        raise ValueError("matrix must be square")
    # Work on a copy to avoid mutating the caller's matrix.
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Find a pivot in column k at or below row k.
        if a[k][k] == 0:
            for r in range(k + 1, n):
                if a[r][k] != 0:
                    a[k], a[r] = a[r], a[k]
                    sign = -sign
                    break
            else:
                return 0
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]
