from collections import deque

def solve(n, edges):
    """Smallest total weight from node 0 to node n-1 in an undirected
    weighted graph, or -1 if unreachable. SPFA (queue-based Bellman-Ford),
    so it is correct even if some weights are not positive."""
    try:
        n = int(n)
    except (TypeError, ValueError):
        return -1
    if n <= 0:
        return -1
    if n == 1:
        return 0
    adj = [[] for _ in range(n)]
    if edges:
        for edge in edges:
            a, b, w = edge
            if not (0 <= a < n and 0 <= b < n):
                continue
            adj[a].append((b, w))
            adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[0] = 0
    in_queue = [False] * n
    queue = deque([0])
    relaxations = 0
    max_relaxations = max(1, n * len(edges) + n)
    while queue:
        u = queue.popleft()
        in_queue[u] = False
        for v, w in adj[u]:
            nd = dist[u] + w
            if nd < dist[v]:
                dist[v] = nd
                if not in_queue[v]:
                    in_queue[v] = True
                    queue.append(v)
        relaxations += 1
        if relaxations > max_relaxations:
            break  # safety valve against pathological/negative cycles
    return dist[n - 1] if dist[n - 1] < INF else -1

